    correctKey: 'D',
    explanation: `場所打ちコンクリート杭は、地盤を掘削して鉄筋かごを建て込み、コンクリートを打設して現場で杭を築造する工法である。アースドリル工法は表層ケーシングを設置し、以深はベントナイトなどの安定液で孔壁を保護する。リバースサーキュレーション工法は、孔内水位を地下水位より2m以上高く保ち、その静水圧で孔壁を保護しながら、泥水を循環させて掘りくずを排出する。オールケーシング工法はケーシングチューブを全長にわたり圧入するので孔壁保護が確実である。いずれの工法でも、孔底に堆積したスライムは杭の先端支持力を著しく低下させるため、一次処理と二次処理により確実に除去する。

【図解】場所打ち杭の工法と孔壁保護
　工法｜孔壁保護の方法
　アースドリル工法｜表層ケーシングと安定液
　リバースサーキュレーション工法｜孔内水位を高く保つ静水圧
　オールケーシング工法｜ケーシングチューブの全長圧入
　⇒ スライム処理は一次と二次の二段階で行う
　⚠ スライムの残存は先端支持力を失わせる`,
    difficulty: 'standard',
