    question: '寒中コンクリートに関する記述として、最も適当なものはどれか。',
    choices: [
      { key: 'A', text: '打込み後の初期凍害を防ぐため、圧縮強度が5N/mm²に達するまで初期養生を行う。', explanation: '適当。初期凍害を防ぐ最低限の強度である。' },
      { key: 'B', text: '寒中コンクリートは、日平均気温が10度以下となる期間に適用する。', explanation: '不適当。正しくは、日平均気温が4度以下となる期間である。' },
      { key: 'C', text: '練混ぜ水と骨材を加熱する場合、セメントも直接加熱するのがよい。', explanation: '不適当。正しくは、セメントは直接加熱してはならない。' },
      { key: 'D', text: '寒中コンクリートでは、AE剤を用いてはならない。', explanation: '不適当。正しくは、耐凍害性を高めるためAE剤を用いる。' },
    ],
    correctKey: 'A',
    explanation: `寒中コンクリートは、日平均気温が4度以下となることが予想される期間に施工するコンクリートである。凝結硬化の初期に凍結すると組織が破壊されて強度が回復しないので、初期凍害の防止が最大の課題となる。打込み後は、圧縮強度が5N/mm²に達するまで、コンクリート温度を5度以上に保つ初期養生を行う。材料の加熱は、練混ぜ水と骨材について行い、セメントは品質を損なうため直接加熱してはならない。練混ぜ水は加熱してもセメント投入前に骨材と混合して温度を下げ、セメントの急結を防ぐ。また空気連行によって耐凍害性が高まるので、AE剤またはAE減水剤を用いる。

【図解】寒中コンクリートの管理
　項目｜内容
　適用期間｜日平均気温4度以下が予想される期間
　初期養生｜圧縮強度5N/mm²に達するまで
　養生温度｜コンクリート温度5度以上を保つ
　加熱してよい材料｜練混ぜ水と骨材のみ
　⇒ AE剤の使用で耐凍害性を高める
　⚠ セメントを直接加熱してはならない`,
